import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem =
    items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Pricing 2' };
  const headlineText = String(headlineItem.text ?? 'Pricing 2').replace(
    /[^\x00-\x7F]/g,
    ''
  );

  const group = new Group();
  group.name = 'hub-pricing-card-0-label-sprite';

  // ---- atlas region aspect ratio (512 x 320) ----
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;
  const plateWidth = 1.4;
  const plateHeight = plateWidth / aspect;

  const inkColor = new THREE.Color(colors.ink);
  const surfaceColor = new THREE.Color(colors.surface);
  const accentColor = new THREE.Color(colors.accent);
  const paperColor = new THREE.Color(colors.paper);

  // ---- engineered gradient plate (base, no grain yet) ----
  const plateGeo = new PlaneGeometry(plateWidth, plateHeight, 1, 1);
  const plateMat = new MeshBasicNodeMaterial({ transparent: true });
  const gradientNode = mix(
    vec3(inkColor.r, inkColor.g, inkColor.b),
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    uv().y
  );
  plateMat.colorNode = gradientNode;
  plateMat.opacity = 1;

  const plateMesh = new Mesh(plateGeo, plateMat);
  plateMesh.position.set(0, 0, 0);
  group.add(plateMesh);

  // ---- accent underline (signal red, <10% of frame area) ----
  const accentGeo = new PlaneGeometry(plateWidth * 0.5, plateHeight * 0.06);
  const accentMat = new MeshBasicNodeMaterial({ transparent: true });
  accentMat.colorNode = vec3(accentColor.r, accentColor.g, accentColor.b);
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -plateHeight * 0.36, 0.01);
  group.add(accentMesh);

  // ---- headline text: "Pricing 2" ----
  const textObj = ctx.fontAtlas.createText(headlineText, {
    fontSize: 39,
    color: colors.paper,
    align: 'center',
  });
  textObj.position.set(0, plateHeight * 0.06, 0.02);
  group.add(textObj);

  // ---- grain texture load (async, cached) ----
  let grainTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      grainTex = tex;
      grainTex.wrapS = THREE.RepeatWrapping;
      grainTex.wrapT = THREE.RepeatWrapping;
      const grainSample = texture(grainTex, uv());
      const grainInfluence = grainSample.r.mul(0.15).add(0.9);
      plateMat.colorNode = gradientNode.mul(grainInfluence);
      plateMat.needsUpdate = true;
    });
  }

  // ---- billboard toward camera ----
  group.onBeforeRender = function (renderer, scene, camera) {
    this.quaternion.copy(camera.quaternion);
  };

  // ---- weighted-settle entrance (static composition, single entrance only) ----
  plateMat.opacity = 0;
  accentMat.opacity = 0;
  textObj.traverse((child) => {
    if (child.material) child.material.transparent = true;
  });
  group.scale.set(0.96, 0.96, 0.96);
  group.position.y -= 0.05;

  const tl = gsap.timeline();
  tl.to(group.position, {
    y: group.position.y + 0.05,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(
    [plateMat, accentMat],
    {
      opacity: 1,
      duration: 0.6,
      ease: 'power2.out',
    },
    0
  );
  tl.to(
    group.scale,
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.4,
      ease: 'power2.out',
    },
    0.1
  );
  tl.to(
    group.scale,
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
    },
    0.5
  );

  group.userData.cleanup = () => {
    tl.kill();
    group.onBeforeRender = null;

    plateGeo.dispose();
    plateMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();

    if (grainTex && typeof grainTex.dispose === 'function') {
      grainTex.dispose();
    }

    textObj.traverse((child) => {
      if (child.geometry && typeof child.geometry.dispose === 'function') {
        child.geometry.dispose();
      }
      if (child.material && typeof child.material.dispose === 'function') {
        child.material.dispose();
      }
    });

    group.clear();
  };

  group.userData.handlers = {};

  return group;
}
